use vstd::prelude::*;

verus! {

spec fn eq_prefix(a: Seq<i32>, b: Seq<i32>, k: nat) -> bool {
    k <= a.len()
    && k <= b.len()
    && (forall|j: nat| j < k ==> a[j] == b[j])
}

fn longest_prefix(a: &[i32], b: &[i32]) -> (res: usize)
    ensures
        // result is within bounds
        res <= a@.len(),
        res <= b@.len(),

        // all elements before res match
        eq_prefix(a@, b@, res as nat),

        // maximality: either we reached the min length, or first mismatch at res
        (res == (if a@.len() <= b@.len() { a@.len() } else { b@.len() }) as usize)
          || (a@[res as nat] != b@[res as nat]),
{
    let n = a.len().min(b.len());
    let mut i = 0usize;

    while i < n && a[i] == b[i]
        invariant
            i <= n,
            n <= a@.len(),
            n <= b@.len(),
            eq_prefix(a@, b@, i as nat),
        decreases n - i,
    {
        i += 1;
    }

    i
}

}

